use verus::prelude::*;

verus! {
    /// Given two Vec<i32> of equal length, produce a new Vec<i32> whose
    /// i-th element is arr1[i] + arr2[i].  We assume no overflow/underflow
    /// occurs in any individual addition.
    fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32>
        // Precondition: the two inputs have the same length
        requires arr1.len() == arr2.len()
        // Postcondition: the result has the same length, and each slot
        // is the pointwise sum of the inputs
        ensures |res: &Vec<i32>| 
            res.len() == arr1.len()
            && forall(|i: usize| i < res.len() ==> res[i] == arr1[i] + arr2[i])
    {
        // Allocate an empty vector with capacity = input length
        let mut res: Vec<i32> = Vec::with_capacity(arr1.len());
        let mut i: usize = 0;

        // Loop over indices 0..arr1.len()
        while i < arr1.len()
            invariant i <= arr1.len()
            invariant res.len() == i
            invariant forall(|j: usize| j < i ==> res[j] == arr1[j] + arr2[j])
            decreases arr1.len() - i
        {
            // By our precondition, this addition does not overflow
            let sum: i32 = arr1[i] + arr2[i];
            res.push(sum);
            i += 1;
        }

        res
    }
}